"""Boundary Traversal — three walks stitched together.

Left boundary top-down, then leaves left to right, then right boundary
bottom-up. Leaves are excluded from the two boundary walks so no node repeats.

Time: O(n)   Space: O(h)
"""
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def boundaryTraversal(self, root) -> List[int]:
        if not root:
            return []

        def is_leaf(node) -> bool:
            return not node.left and not node.right

        out = []
        if not is_leaf(root):
            out.append(root.val)

        node = root.left
        while node:
            if not is_leaf(node):
                out.append(node.val)
            node = node.left or node.right

        def leaves(node) -> None:
            if not node:
                return
            if is_leaf(node):
                out.append(node.val)
                return
            leaves(node.left)
            leaves(node.right)

        leaves(root)

        right_side = []
        node = root.right
        while node:
            if not is_leaf(node):
                right_side.append(node.val)
            node = node.right or node.left
        out.extend(reversed(right_side))
        return out
